import{_ as a,o as t,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"FR 3.5.7 - Create Content Request","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-7-create-content-request/spec.md","filePath":"feature/media-package-campaign/3-5-7-create-content-request/spec.md"}'),c={name:"feature/media-package-campaign/3-5-7-create-content-request/spec.md"};function d(r,e,i,s,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="fr-3-5-7-create-content-request" tabindex="-1">FR 3.5.7 - Create Content Request <a class="header-anchor" href="#fr-3-5-7-create-content-request" aria-label="Permalink to &quot;FR 3.5.7 - Create Content Request&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Ready after V2 Mongo migration</td></tr><tr><td>Roles</td><td>Client</td></tr><tr><td>Delivery task</td><td>DA-E50-10</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>A Client creates an out-of-campaign request in a workspace. It starts as <code>PENDING</code> and does not create a task until an Agency Manager accepts it.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li><code>POST /api/v1/workspaces/{workspaceId}/content-requests</code> accepts <code>title</code>, <code>description</code>, Client-selected <code>type</code> (<code>POST|LIVESTREAM|SURVEY</code>), and <code>dueDate</code>; it returns a <code>PENDING</code> request.</li><li>Only a Client belonging to the workspace may create it.</li><li>Confirmed 2026-10-13: creation requires a successfully deployed Campaign in this Workspace; approval alone, a queued/failed/partial deployment, or no Campaign is insufficient. Enforce this on the server as well as in the UI.</li><li>Confirmed 2026-10-14: Campaign must be <code>IN_PROGRESS</code> with deployment <code>SUCCEEDED</code>. Manager marking COMPLETED automatically cancels PENDING Requests with audit history; IN_PROGRESS continues. Calendar expiry alone does not complete Campaign.</li><li>Create/update dueDate is within max(today in Workspace timezone, Campaign startDate) and Campaign endDate, inclusive. See ../request-completion-validation/spec.md.</li><li>Confirmed later 2026-10-14: generated Task maps type/due date and belongs to the current deployed Campaign; campaignWorkItemId remains null, sourceType=CONTENT_REQUEST/sourceRefId retain provenance. No change to approved plan or package quantities. See ../campaign-closure/spec.md.</li></ul><h2 id="ui-and-scope" tabindex="-1">UI and scope <a class="header-anchor" href="#ui-and-scope" aria-label="Permalink to &quot;UI and scope&quot;">​</a></h2><p>Use Workspace-scoped requests, real API data, and the existing page layout. New text uses parallel <code>src/i18n/locales/{vi,en}/requests.json</code> keys under <code>requests.v2.*</code> (status, fields, campaignGate and error/action text). Use semantic theme tokens in light/dark mode; loading, empty, validation, forbidden and retry states must be usable on mobile. Do not repurpose unrelated Client-profile screens or the content editor.</p><h2 id="persistence-rule" tabindex="-1">Persistence rule <a class="header-anchor" href="#persistence-rule" aria-label="Permalink to &quot;Persistence rule&quot;">​</a></h2><p>Init and the new migration now describe V2 fields <code>workspaceId</code>, <code>requestedBy</code>, <code>title</code>, <code>description</code>, <code>type</code>, <code>dueDate</code>, <code>status</code>, <code>generatedTaskId</code>, <code>version</code>, <code>createdAt</code>, and <code>updatedAt</code>, with review/audit metadata as defined in the shared plan. Read-only Atlas inventory on 2026-10-13 found zero records and legacy indexes; migration has NOT been applied. Allowed statuses are <code>PENDING</code>, <code>IN_PROGRESS</code>, <code>ACCEPTED</code>, <code>DENIED</code>, <code>CANCELLED</code>. Do not rerun Mongo initialisation or guess mappings for legacy approval/task states.</p>',10)])])}const h=a(c,[["render",d]]);export{m as __pageData,h as default};
